  ('3bff41f9-a253-4592-87a7-38d99c60f711', 'e3f4a5b6-7c8d-4e63-8f23-3a4b5c6d7e53', 'e7de6880-b7c5-4ed7-81d5-fa12ba7ad55f', 'subtopic'::public.curated_course_node_type, 'Questions, claims, and evidence', 'Students learn to turn broad political claims into empirical questions that can be tested with data.', 0),
