update public.learning_paths
set
  title = 'Statistics for Political Science',
  goal = 'Statistics for Political Science',
  summary = 'The course is designed as a 15-week semester with weekly labs. The sequence begins with political measurement and statistical inference, moves through regression and causal inference, and ends with a reproducible empirical brief using real political data.',
  data = $stpsjson${"slug": "statistics-for-political-science", "title": "Statistics for Political Science", "description": "The course is designed as a 15-week semester with weekly labs. The sequence begins with political measurement and statistical inference, moves through regression and causal inference, and ends with a reproducible empirical brief using real political data.", "topics": [{"id": "e7de6880-b7c5-4ed7-81d5-fa12ba7ad55f", "type": "topic", "title": "Statistical Thinking for Political Science and Public Affairs", "description": "This opening unit frames statistics as a way to reason about political evidence, uncertainty, and competing explanations rather than as a detached math toolkit.", "children": [{"id": "3bff41f9-a253-4592-87a7-38d99c60f711", "type": "subtopic", "title": "Questions, claims, and evidence", "children": [{"id": "3ee5c2f1-b1a3-41f8-9a73-6e65208688f9", "type": "concept", "title": "descriptive versus explanatory questions"}, {"id": "60fc0284-2fb2-472a-9846-1c6ac8623903", "type": "concept", "title": "units of analysis"}, {"id": "ea664b9c-47c6-4d9d-9b48-221006d2a57c", "type": "concept", "title": "scope conditions"}], "description": "Students learn to turn broad political claims into empirical questions that can be tested with data."}, {"id": "a9ee58e0-c8ba-468a-b2d4-afea01d811f6", "type": "subtopic", "title": "Variation and uncertainty", "children": [{"id": "c39d4c5c-3a2c-4273-b8da-d1af2c902fbf", "type": "concept", "title": "individual-level variation"}, {"id": "c7617c7f-ccbe-40f0-8898-3a0165005f75", "type": "concept", "title": "aggregate variation"}, {"id": "a3584369-bbdf-4a45-a7f3-e5a01921b605", "type": "concept", "title": "sampling variability"}], "description": "Political data are noisy; this subtopic explains why variation is information to be modeled, not merely a nuisance."}, {"id": "99e4b0ac-b7e3-4e9e-bebd-1216c533606e", "type": "subtopic", "title": "Quantitative reasoning in political argument", "children": [{"id": "c98642d0-a126-48a9-a8e5-1bdd10dff818", "type": "concept", "title": "effect size"}, {"id": "91726e9f-2264-4a82-8e9e-a746a57e9eea", "type": "concept", "title": "uncertainty language"}, {"id": "ccfd0dce-69fb-4600-a95f-cba35e03d013", "type": "concept", "title": "claims versus evidence"}], "description": "Students practice reading statistical claims in public debate and identifying what the numbers can and cannot support."}]}, {"id": "d1b1f46c-17ed-4648-858a-53660efb4cbe", "type": "topic", "title": "Political Data, Measurement, and Research Questions", "description": "A political statistics course starts with measurement: variables such as democracy, ideology, turnout, or trust are constructed from imperfect observations.", "children": [{"id": "d944cfdf-6058-4098-bfc8-3f832c23c781", "type": "subtopic", "title": "Concept formation and operationalization", "children": [{"id": "e864209b-f816-445b-8e3b-782b7ba7e624", "type": "concept", "title": "validity"}, {"id": "d90023aa-2bab-4f94-a5b7-045b6e2042bf", "type": "concept", "title": "reliability"}, {"id": "dd01fa2a-d68e-4697-9870-7de6944ce8b7", "type": "concept", "title": "latent constructs"}], "description": "Students connect abstract political concepts to measurable indicators."}, {"id": "4f1259b7-7c93-4b9f-8e60-a5479249a682", "type": "subtopic", "title": "Data structures in political science", "children": [{"id": "fa214a82-23f0-4755-9250-3d374ae7b28b", "type": "concept", "title": "cross-sectional data"}, {"id": "fe0e2719-5126-4563-bb05-469f647fc252", "type": "concept", "title": "time-series data"}, {"id": "0d371d2f-86e5-4b21-8acd-7015300657f9", "type": "concept", "title": "panel data"}, {"id": "83d35389-4d71-48ec-bc8d-32fd665cb8c3", "type": "concept", "title": "dyadic data"}], "description": "Students learn how surveys, elections, roll calls, country-years, events, and texts differ analytically."}, {"id": "f9f74d0c-05da-44a1-80cb-65ae41dbbfaf", "type": "subtopic", "title": "Data quality and missingness", "children": [{"id": "94dcde7b-8258-4cd1-abf9-dc5e919a26c1", "type": "concept", "title": "missing completely at random"}, {"id": "af48709d-0f3e-4d3c-ad69-d6a88ae6ce6c", "type": "concept", "title": "nonresponse"}, {"id": "46eb4e6a-c038-4cc4-80c6-49459f75928c", "type": "concept", "title": "administrative data limits"}], "description": "Students learn to diagnose whether gaps, miscoding, or measurement error could distort conclusions."}]}, {"id": "eaa325f6-4c01-478b-880b-e5c5065f1bd2", "type": "topic", "title": "Descriptive Statistics, Distributions, and Data Visualization", "description": "This unit builds fluency in summarizing political datasets before moving to inference or modeling.", "children": [{"id": "409bbe24-c470-4815-889e-4471ef3befa8", "type": "subtopic", "title": "Centers and spreads", "children": [{"id": "6790beac-b527-4c52-be0e-f579a41f8336", "type": "concept", "title": "mean versus median"}, {"id": "fe5cd542-ccc7-4d38-842b-ccddf6f639d1", "type": "concept", "title": "interquartile range"}, {"id": "8911b195-6a92-4411-92e7-92579e3d5d46", "type": "concept", "title": "standardization"}], "description": "Students learn how means, medians, proportions, variance, and standard deviation summarize political outcomes."}, {"id": "c0b6cfb9-2c8e-426a-bad4-8f7676792cb6", "type": "subtopic", "title": "Distributional thinking", "children": [{"id": "680cb7f9-fa02-4e80-8d24-38252356410a", "type": "concept", "title": "histograms"}, {"id": "4359ecac-0431-483b-b1ed-616a6301eca3", "type": "concept", "title": "density plots"}, {"id": "a17786bf-23b6-4bd5-88ef-f8a18bc28b8b", "type": "concept", "title": "skewness"}, {"id": "e7c1ed66-bea0-4ebb-8321-3d646ae29f99", "type": "concept", "title": "outliers"}], "description": "Students inspect the shape of political data and learn why outliers and skew matter."}, {"id": "bae018a2-cdad-470b-b859-3dcfd155c0df", "type": "subtopic", "title": "Political data visualization", "children": [{"id": "de7e1b18-bf6f-41d4-9480-5decb9c2d40f", "type": "concept", "title": "bar charts and dot plots"}, {"id": "2a803c2e-6247-4096-b5f7-c3adc035ebda", "type": "concept", "title": "scatterplots"}, {"id": "76157b4a-e282-45ec-a72d-5151d6420348", "type": "concept", "title": "small multiples"}, {"id": "650afd0d-bc16-4e5e-98a8-95e23a6ce576", "type": "concept", "title": "maps with caution"}], "description": "Students use graphics to reveal patterns without overstating certainty."}]}, {"id": "90d9ab25-89fd-408b-a284-e3529c6e2f2a", "type": "topic", "title": "Probability, Random Variables, and Political Uncertainty", "description": "Probability gives students the language to describe uncertainty in elections, surveys, policy outcomes, and institutional behavior.", "children": [{"id": "0824cef2-3937-4184-89d1-cd6846623f4a", "type": "subtopic", "title": "Probability rules", "children": [{"id": "408ddb66-b3bf-40b2-8581-18e8eeccfe58", "type": "concept", "title": "joint probability"}, {"id": "a268e293-5895-44a7-9c87-bf7456c47f98", "type": "concept", "title": "conditional probability"}, {"id": "3ec4c96c-59c3-4899-8eab-8570a9dfad56", "type": "concept", "title": "independence"}], "description": "Students learn the basic arithmetic of uncertainty needed for later inference."}, {"id": "edcd064d-3fa2-4109-88c0-89a75c041f67", "type": "subtopic", "title": "Random variables and expected values", "children": [{"id": "086f70b7-a45f-47cd-8980-7d41e6fc7af6", "type": "concept", "title": "Bernoulli and binomial variables"}, {"id": "ae32bea3-1053-41e4-96f2-483bb7cc7201", "type": "concept", "title": "normal approximation"}, {"id": "e42bb2d2-e59f-4d2b-875c-363d0abba6c4", "type": "concept", "title": "expectation and variance"}], "description": "Students model uncertain political quantities as variables with distributions."}, {"id": "6d5f6521-4a26-44d7-b727-5373c9004e0d", "type": "subtopic", "title": "Bayesian intuition", "children": [{"id": "6be5b2f0-8ed3-453d-a41e-e28a925418a3", "type": "concept", "title": "prior beliefs"}, {"id": "28320504-52dc-4b87-94c4-47568ddf0441", "type": "concept", "title": "likelihood"}, {"id": "5676a745-a406-438c-a307-931b5afbdfae", "type": "concept", "title": "posterior reasoning"}], "description": "Students encounter Bayes' rule as a disciplined way to update beliefs when new evidence arrives."}]}, {"id": "4dc752a3-7fbf-4120-a856-27a460ff4081", "type": "topic", "title": "Sampling, Surveys, Polling, and Public Opinion Inference", "description": "Political science relies heavily on samples, especially in public opinion, so students need a realistic view of sampling, weighting, and polling error.", "children": [{"id": "ce0899aa-d20a-4c00-b2aa-2ee815d50209", "type": "subtopic", "title": "Sampling designs", "children": [{"id": "a5e6fb33-1e53-4c38-a4e0-f704ae126656", "type": "concept", "title": "sampling frame"}, {"id": "6d9b81fa-8501-4a76-a295-2b139037463f", "type": "concept", "title": "stratification"}, {"id": "098db1c1-0bc1-4ca5-a24a-da8b475d0c5d", "type": "concept", "title": "cluster sampling"}], "description": "Students compare simple random samples with stratified, cluster, and multistage survey designs."}, {"id": "216eba09-b7ec-430b-93ac-a789a0d71c78", "type": "subtopic", "title": "Polling and survey error", "children": [{"id": "8c3d0d8c-704a-45e7-978f-78b1544e18e7", "type": "concept", "title": "margin of error"}, {"id": "1b007085-1fa9-4fb1-964d-f8f5e0c97c78", "type": "concept", "title": "nonresponse"}, {"id": "a5861089-3a75-4ee4-b23b-92a2ab3f999b", "type": "concept", "title": "likely voter models"}, {"id": "922a6b71-0511-4997-8e6c-9373adbe4ef1", "type": "concept", "title": "mode effects"}], "description": "Students learn why poll results can miss the truth even when sampling is careful."}, {"id": "a60145fe-16bd-4a4e-b109-f54f1d3af084", "type": "subtopic", "title": "Weights and representativeness", "children": [{"id": "11e6680f-a85b-4099-a8f0-9e133bf8c30c", "type": "concept", "title": "post-stratification"}, {"id": "327bb23a-e54e-441c-8b1e-0fbd080e4d6f", "type": "concept", "title": "raking"}, {"id": "61e57009-69ad-4a52-b2be-9fd587a6d291", "type": "concept", "title": "design effects"}], "description": "Students learn how survey weights are used and why they are not magic fixes."}]}, {"id": "2a35cf91-3a99-4338-9679-b6df857059f0", "type": "topic", "title": "Estimation, Confidence Intervals, and Hypothesis Testing", "description": "This unit gives students the core tools for moving from observed political data to claims about broader populations or processes.", "children": [{"id": "2ad2e7c0-f7ff-4fcd-bfce-fb3045f6a26c", "type": "subtopic", "title": "Point estimates and standard errors", "children": [{"id": "5cd25ebe-3ae9-4074-a605-ce09c4e6a26e", "type": "concept", "title": "sample proportions"}, {"id": "08e1bedc-7f83-4174-be3e-a2ada4b4becc", "type": "concept", "title": "sample means"}, {"id": "c71ff1e3-a2b9-412b-99a0-3ad742bdb0a4", "type": "concept", "title": "standard error"}], "description": "Students learn the difference between an estimate and the uncertainty around it."}, {"id": "69fed2b6-a45a-47df-8ab9-b76b35972156", "type": "subtopic", "title": "Confidence intervals", "children": [{"id": "dd3bce48-64b5-4e4c-a250-2094b92cbd22", "type": "concept", "title": "interval width"}, {"id": "71616e7d-5b64-4bc5-9c8d-0b9bc88bb038", "type": "concept", "title": "confidence level"}, {"id": "0a17e8ca-3d57-4773-8fc5-89f52ed99c5f", "type": "concept", "title": "practical significance"}], "description": "Students practice interpreting intervals as uncertainty ranges, not as yes-or-no proof."}, {"id": "58a30b75-7a50-4bac-9c52-1d45f86bd1e2", "type": "subtopic", "title": "Hypothesis tests and p-values", "children": [{"id": "05a3f7ec-0ad6-4328-89f3-13536128ca9e", "type": "concept", "title": "null hypotheses"}, {"id": "e2c7aab5-be75-4f48-ab97-2be3c2019786", "type": "concept", "title": "Type I and Type II error"}, {"id": "b7385cdf-2788-4fd8-94b3-c4c9acaf46a1", "type": "concept", "title": "multiple comparisons"}], "description": "Students learn how tests work and why statistical significance must be interpreted carefully."}]}, {"id": "4ec58e61-905c-43b5-a3dc-2b5f2e51828c", "type": "topic", "title": "Bivariate Relationships: Cross-Tabs, Difference in Means, and Correlation", "description": "Before multivariate modeling, students need to understand simple relationships among political variables and the limits of two-variable evidence.", "children": [{"id": "2852ced7-2e36-45ec-9f7d-7d08e84491a9", "type": "subtopic", "title": "Cross-tabulation and chi-square", "children": [{"id": "8ff44862-464d-45c8-8201-d49ab3d06faf", "type": "concept", "title": "row and column percentages"}, {"id": "72ce8f58-4ff2-4483-a944-264d4a2d21da", "type": "concept", "title": "expected counts"}, {"id": "c8bbf3f3-21e6-4e0a-874f-92853fb0d34e", "type": "concept", "title": "chi-square tests"}], "description": "Students analyze relationships between categorical political variables such as party ID and vote choice."}, {"id": "57676874-8e1a-4509-ac51-6cdc5a472296", "type": "subtopic", "title": "Group comparisons", "children": [{"id": "ac3b81a6-1b01-4192-95ae-4a6b5519ae39", "type": "concept", "title": "difference in means"}, {"id": "b0d5f9cf-917b-4817-8bb2-5aef7ec0c112", "type": "concept", "title": "t-tests"}, {"id": "ad3906f7-2224-4619-8be4-3c2df5b433c1", "type": "concept", "title": "ANOVA overview"}], "description": "Students compare average outcomes across parties, regions, treatments, or demographic groups."}, {"id": "9c2e26cb-122d-4bb4-9acd-dc3d63c578c9", "type": "subtopic", "title": "Correlation and association", "children": [{"id": "0878a525-b476-489d-bb0d-e31e29ea1493", "type": "concept", "title": "Pearson correlation"}, {"id": "c685734d-a6e3-47af-90bc-92790361f852", "type": "concept", "title": "scatterplots"}, {"id": "80835d38-2e3e-4508-b796-4739c4253790", "type": "concept", "title": "ecological fallacy"}], "description": "Students learn how correlation summarizes linear association without establishing causation."}]}, {"id": "32db845d-ad99-4bd5-873f-ee8757712864", "type": "topic", "title": "Linear Regression for Political Science", "description": "Regression becomes the workhorse for estimating relationships in political science, policy, and international relations.", "children": [{"id": "6422cb59-50df-415f-80b6-a1c8825e050e", "type": "subtopic", "title": "Simple linear regression", "children": [{"id": "f1585409-7e5f-41c3-bb67-c343b8c31efb", "type": "concept", "title": "least squares"}, {"id": "558dd4f9-8dd3-4ef4-9b2f-637837a8c648", "type": "concept", "title": "residual plots"}, {"id": "3c343dbc-29a9-4bc4-9a13-1f2eb96cbfd0", "type": "concept", "title": "R-squared"}], "description": "Students learn slope, intercept, fitted values, residuals, and substantive interpretation."}, {"id": "f67cf113-f3a2-4514-a2c7-d2478666b5a0", "type": "subtopic", "title": "Regression inference", "children": [{"id": "24a7d4de-3614-4a41-a0ed-b79935afa759", "type": "concept", "title": "standard errors"}, {"id": "76452287-3988-4ae7-8f62-f6d244c79652", "type": "concept", "title": "confidence intervals"}, {"id": "e28a9c10-93e0-4ebc-9ff9-9e145068d8ee", "type": "concept", "title": "t-statistics"}], "description": "Students connect regression coefficients to uncertainty and hypothesis tests."}, {"id": "25be6196-ddf3-45d8-a7d7-8ea941d614a4", "type": "subtopic", "title": "Substantive effects", "children": [{"id": "7a86a618-0aa4-4060-aa2a-7206da16dd4e", "type": "concept", "title": "first differences"}, {"id": "af717721-ca1a-4b36-8cb1-26b302a24a25", "type": "concept", "title": "predicted values"}, {"id": "293fe1d9-84d0-4bb6-a6c6-b59ce5dbb199", "type": "concept", "title": "marginal interpretation"}], "description": "Students translate coefficients into meaningful political quantities."}]}, {"id": "23d08eb1-a75c-4460-98ed-4feca208202f", "type": "topic", "title": "Multiple Regression, Confounding, and Model Interpretation", "description": "This unit teaches students how regression changes when several explanations compete and how to interpret models without overclaiming causality.", "children": [{"id": "251fc047-8fff-409b-9a44-76643c542153", "type": "subtopic", "title": "Control variables and confounding", "children": [{"id": "9f3fb5d1-5a5d-486a-9d74-03d3cf7ab059", "type": "concept", "title": "backdoor logic"}, {"id": "c98a6722-6d4c-4a24-9fd8-503a46b94436", "type": "concept", "title": "selection bias"}, {"id": "e876b551-6397-4a79-8a38-d0b2acb28a62", "type": "concept", "title": "post-treatment controls"}], "description": "Students learn why omitted variables can distort estimated relationships."}, {"id": "31fbf9fa-a023-43f6-a011-22327d73736d", "type": "subtopic", "title": "Model specification", "children": [{"id": "405f56c2-fe38-457f-b053-f361dc2c5672", "type": "concept", "title": "dummy variables"}, {"id": "584ccd5e-eba3-4d3e-b396-42d17cbdc926", "type": "concept", "title": "interactions"}, {"id": "f172f63d-f0d3-44a3-a23b-3dda2b01b5fb", "type": "concept", "title": "nonlinearity"}], "description": "Students compare alternative functional forms and diagnose whether assumptions are plausible."}, {"id": "10299aa1-beb7-4d5f-b1a0-2a002447b236", "type": "subtopic", "title": "Regression diagnostics", "children": [{"id": "d4538d8b-1f98-4a39-a24a-38d24f3cda73", "type": "concept", "title": "heteroskedasticity"}, {"id": "71b0b679-528e-4b63-8501-392f6ee19e12", "type": "concept", "title": "multicollinearity"}, {"id": "9c30bbd4-a987-453c-b3a0-d140eed8ff20", "type": "concept", "title": "influential observations"}], "description": "Students learn practical checks that prevent careless model use."}]}, {"id": "68fbb1d1-cd54-47cd-be63-925c49d8a7ac", "type": "topic", "title": "Categorical Outcomes: Logistic Regression and Classification", "description": "Many political outcomes are categorical, such as voting, protest participation, conflict onset, or policy adoption.", "children": [{"id": "65ae3fad-60d4-4c70-9612-1f78d6029052", "type": "subtopic", "title": "Binary outcomes", "children": [{"id": "90f12b78-0c80-4589-9af0-6e5e7872555d", "type": "concept", "title": "probability bounds"}, {"id": "45e1c243-c86b-4576-96ea-f317a86ef793", "type": "concept", "title": "log odds"}, {"id": "09cbec7d-e440-40d7-8a1e-ddcb1e81e18e", "type": "concept", "title": "logit link"}], "description": "Students learn why linear models can be inadequate for yes/no political outcomes."}, {"id": "4fe9ff96-47c7-490b-b92b-a49db2a46176", "type": "subtopic", "title": "Logistic regression interpretation", "children": [{"id": "3ac6fc0c-d8f8-47fd-b628-7eea0ce3431e", "type": "concept", "title": "odds ratios"}, {"id": "c63fb51f-4363-4034-99f9-e5f577e01c88", "type": "concept", "title": "average marginal effects"}, {"id": "318b0414-4fba-40ea-b4e8-ad373511f983", "type": "concept", "title": "classification thresholds"}], "description": "Students translate logit results into predicted probabilities and first differences."}, {"id": "c617f15a-232f-4ecd-a5ee-70b87f785c44", "type": "subtopic", "title": "Model performance", "children": [{"id": "e42b0333-3dab-4d7f-9759-253f0bfe4dfa", "type": "concept", "title": "confusion matrices"}, {"id": "c1f0208d-c4ac-4901-bb63-38bcab8c12d3", "type": "concept", "title": "ROC curves"}, {"id": "44eea6dd-8f9c-4413-807c-9d1759b92a9f", "type": "concept", "title": "calibration"}], "description": "Students learn basic classification evaluation without confusing prediction with explanation."}]}, {"id": "771ce7fb-bcee-4fde-bbef-446fffcfe723", "type": "topic", "title": "Causal Inference: Experiments, Natural Experiments, and Identification", "description": "This unit lifts the course toward contemporary political methodology by separating causal questions from ordinary association.", "children": [{"id": "06d40df6-8e4e-4274-9af9-28c5625e8906", "type": "subtopic", "title": "Potential outcomes framework", "children": [{"id": "01e4f811-0587-4948-a66c-3ed10b97c8ce", "type": "concept", "title": "treatment effects"}, {"id": "0df27d17-6272-4b19-949d-609fafbe817c", "type": "concept", "title": "counterfactuals"}, {"id": "8899f962-a4a8-4c98-9314-6ca7cbe6dad3", "type": "concept", "title": "SUTVA"}], "description": "Students learn the logic behind causal effects and the fundamental problem of causal inference."}, {"id": "5850ee57-2e96-4d56-9b2d-291f2d545f41", "type": "subtopic", "title": "Experiments and field experiments", "children": [{"id": "efb1e43c-f4cc-4c58-bde8-ce77e85fcc31", "type": "concept", "title": "randomization"}, {"id": "3ad9b063-9115-49a3-acec-f82a99f147cf", "type": "concept", "title": "balance"}, {"id": "534a884e-6fef-4b6b-a0db-862350e3f892", "type": "concept", "title": "ethical constraints"}], "description": "Students examine random assignment in lab, survey, and field settings."}, {"id": "2877f1aa-aca4-4ca7-a14a-5e34e957930b", "type": "subtopic", "title": "Quasi-experimental designs", "children": [{"id": "ff281a03-03f1-4685-bdcc-de539f1f2aa3", "type": "concept", "title": "difference-in-differences"}, {"id": "08bc9d79-2502-4e7c-b3ca-d15f6e7801e4", "type": "concept", "title": "regression discontinuity"}, {"id": "42cba334-b283-4c20-95b7-ddc068ec8490", "type": "concept", "title": "instrumental variables"}, {"id": "859c0c00-77b5-4d15-aef7-070f3c04ea5c", "type": "concept", "title": "matching"}], "description": "Students learn the gist of modern identification strategies used in political science."}]}, {"id": "3729ab32-3572-4c4e-98c7-5c34a615d992", "type": "topic", "title": "Time Series, Panel Data, and Comparative Political Data", "description": "Political outcomes often unfold over time and across units, so students need tools for repeated observations and comparative data.", "children": [{"id": "197e4ddc-7ec0-44e4-8700-356c178dd03e", "type": "subtopic", "title": "Time series basics", "children": [{"id": "b0ca627f-1cb2-4e6a-b233-f2d00d53ab61", "type": "concept", "title": "trends"}, {"id": "ead37d17-765c-4dcf-a5cd-c0e1aab5f946", "type": "concept", "title": "seasonality"}, {"id": "ff5f44ce-eb82-4b90-ba73-4fab6bad35fe", "type": "concept", "title": "autocorrelation"}], "description": "Students learn why temporal dependence changes how evidence should be interpreted."}, {"id": "24b56557-71ad-40d1-94ee-61c987bf34ad", "type": "subtopic", "title": "Panel data logic", "children": [{"id": "037262fa-2953-4b2d-8e64-2c6e548c05a0", "type": "concept", "title": "unit fixed effects"}, {"id": "3a2011c8-2f4f-47de-b0ef-b0a09888c4de", "type": "concept", "title": "time fixed effects"}, {"id": "fa619715-28b4-4cd1-b391-fbcf5311ecbd", "type": "concept", "title": "within-unit change"}], "description": "Students analyze countries, states, districts, or individuals observed repeatedly."}, {"id": "df492c25-7680-4198-b2e9-32fe1440e606", "type": "subtopic", "title": "Comparative datasets", "children": [{"id": "b8f9b047-6d26-4296-9669-838339a0eddb", "type": "concept", "title": "V-Dem"}, {"id": "d47acce3-cacc-4c5d-97ca-8972b9b2b6c3", "type": "concept", "title": "World Bank data"}, {"id": "5120fac7-6ef1-42bd-b13a-0d555785d6e3", "type": "concept", "title": "Quality of Government"}, {"id": "cbba47c1-a828-4801-af02-e342eb0d395f", "type": "concept", "title": "Correlates of War"}], "description": "Students practice using country-level and institutional datasets while respecting measurement limits."}]}, {"id": "c9d55fff-6aca-4f0d-ac6d-15ba36accc86", "type": "topic", "title": "Election, Legislative, and Democracy Data Applications", "description": "Applications anchor statistical tools in recognizable political science problems and data sources.", "children": [{"id": "58953255-d375-4997-8e4d-4309fdcfa01b", "type": "subtopic", "title": "Election and voting data", "children": [{"id": "9b19ee6e-ba31-4eb1-9938-e72624514332", "type": "concept", "title": "ANES"}, {"id": "58697c1d-ad2c-42c1-b50f-23abf321a866", "type": "concept", "title": "MIT Election Data and Science Lab"}, {"id": "4e363900-fc2e-458e-8149-3eef204b8448", "type": "concept", "title": "FiveThirtyEight-style polling data"}], "description": "Students analyze turnout, vote choice, polling, and election returns."}, {"id": "42f80a92-3d79-4fe5-bfd6-ebd5811abbe9", "